INSERT INTO `klasifikasi_arsips` VALUES (2869, NULL, '2023-04-18 00:00:00', '2023-04-18 00:00:00', '900.1.9 Penyusunan Anggaran Pilkada dan Biaya Bantuan Pemilu Dari APBD meliputi: Kebijakan Keuangan Pilkada dan Penyusunan Anggaran Bantuan Pemilu, Peraturan/Pedoman/Standar Belanja Pegawai, Barang dan Jasa, Operasional dan Kontingensi untuk Biaya Pilkada dan Bantuan Pemilu, Bahan Usulan Rencana Kegiatan dan Anggaran (RKA) Pilkada KPUD dan Panwasda Kota, PPK, PPS, KPPS dan Permohonan Pengajuan RKA KPUD dan Panwas, Berkas Pembahasan RKA Pilkada dan Bantuan Pemilu, Rencana Anggaran Satuan Kerja (RASK) Pilkada dan Bantuan Pemilu Kota, Dokumen Rancangan Anggaran Satuan Kerja (DRASK) Pilkada KPUD dan Panwas Kota dan Bantuan Biaya Pemilu dari APBD, Berkas Pembentukan Dana Cadangan Pilkada, Bahan Rapat Rancangan Peraturan Daerah tentang Pilkada, dan Bantuan Biaya Pemilu dari APBD, Nota Persetujuan DPRD tentang Perda APBD Pilkada dan Bantuan Biaya Pemilu dari APBD  ', '', '', 1, 1, 1, '');
INSERT INTO `klasifikasi_arsips` VALUES (2870, NULL, '2023-04-18 00:00:00', '2023-04-18 00:00:00', '900.1.10 Pelaksanaan Anggaran PILKADA dan Anggaran Biaya Bantuan Pemilu   ', '', '', 1, 1, 1, '');
