INSERT INTO `klasifikasi_arsips` VALUES (2872, NULL, '2023-04-18 00:00:00', '2023-04-18 00:00:00', '900.1.10.2 Berkas Penerimaan Komisi, Rabat Pembayaran Pengadaan Jasa, Bunga, Pelaksanaan Pilkada/Pemilu   ', '', '', 1, 1, 1, '');
INSERT INTO `klasifikasi_arsips` VALUES (2873, NULL, '2023-04-18 00:00:00', '2023-04-18 00:00:00', '900.1.10.3 Berkas setor sisa dana Pilkada/Pemilu termasuk setor komisi pengadaan barang/jasa, rabat, bunga, jasa giro Berkas Penyaluran Biaya Pemilu termasuk diantaranya Bukti Transfer Bank   ', '', '', 1, 1, 1, '');
