INSERT INTO `klasifikasi_arsips` VALUES (2880, NULL, '2023-04-18 00:00:00', '2023-04-18 00:00:00', '900.1.12 Anggaran Daerah   ', '', '', 1, 1, 1, '');
INSERT INTO `klasifikasi_arsips` VALUES (2881, NULL, '2023-04-18 00:00:00', '2023-04-18 00:00:00', '900.1.12.1 Anggaran Daerah   ', '', '', 1, 1, 1, '');
INSERT INTO `klasifikasi_arsips` VALUES (2882, NULL, '2023-04-18 00:00:00', '2023-04-18 00:00:00', '900.1.12.2 Dukungan Teknis Anggaran Daerah   ', '', '', 1, 1, 1, '');
INSERT INTO `klasifikasi_arsips` VALUES (2883, NULL, '2023-04-18 00:00:00', '2023-04-18 00:00:00', '900.1.13 Pendapatan dan Investasi Daerah   ', '', '', 1, 1, 1, '');
INSERT INTO `klasifikasi_arsips` VALUES (2884, NULL, '2023-04-18 00:00:00', '2023-04-18 00:00:00', '900.1.13.1 Pajak Daerah dan Retribusi Daerah Antara lain: fasilitasi pelaksanaan kebijakan standardisasi pajak daerah dan retribusi daerah, penyiapan bahan perumusan bimbingan teknis pajak daerah dan retribusi daerah, penyiapan bahan perumusan analisis dan evaluasi, pemantauan pajak daerah dan retribusi daerah, penyiapan bahan perumusan kebijakan fasilitasi pemberian insentif pajak daerah dan retribusi daerah   ', '', '', 1, 1, 1, '');
INSERT INTO `klasifikasi_arsips` VALUES (2885, NULL, '2023-04-18 00:00:00', '2023-04-18 00:00:00', '900.1.13.2 Badan Usaha Milik Daerah Antara lain: fasilitasi serta bimbingan teknis di bidang usaha milik daerah lembaga keuangan, fasilitas serta bimbingan teknis di bidang badan usaha milik daerah lembaga non keuangan, penyiapan pelaksanaan monitoring dan evaluasi badan usaha milik daerah   ', '', '', 1, 1, 1, '');
INSERT INTO `klasifikasi_arsips` VALUES (2886, NULL, '2023-04-18 00:00:00', '2023-04-18 00:00:00', '900.1.13.3 Badan Layanan Umum Daerah Antara lain: analisis, standardisasi teknis, fasilitasi serta bimbingan teknis, pemantauan dan evaluasi di bidang pola pengelolaan keuangan badan layanan umum daerah, Pembinaan pelaksanaan kebijakan, standardisasi teknis, prosedur dan kriteria, fasilitasi serta bimbingan teknis penerapan pola pengelolaan keuangan keuangan badan layanan umum daerah, Penyiapan pelaksanaan monitoring dan evaluasi pola pengelolaan keuangan badan layanan umum daerah   ', '', '', 1, 1, 1, '');
INSERT INTO `klasifikasi_arsips` VALUES (2887, NULL, '2023-04-18 00:00:00', '2023-04-18 00:00:00', '900.1.13.4 Pengelolaan Kekayaan Daerah Antara lain: fasilitasi serta bimbingan teknis pengelolaan kekayaan, Fasilitasi serta bimbingan teknis investasi daerah, Penyiapan pelaksanaan monitoring dan evaluasi pengelolaan kekayaan dan investasi daerah   ', '', '', 1, 1, 1, '');
INSERT INTO `klasifikasi_arsips` VALUES (2888, NULL, '2023-04-18 00:00:00', '2023-04-18 00:00:00', '900.1.13.5 Pinjam Dan Obligasi Daerah Antara lain: fasilitasi pelaksanaan kebijakan pinjaman dan hibah kepada pemerintah daerah dan/atau badan usaha milik daerah, Fasilitasi pelaksanaan kebijakan obligasi daerah, Fasilitasi pelaksanaan kebijakan dana bergulir yang bersumber dari APBN, Bimbingan teknis obligasi daerah, dana bergulir serta penyertaan modal daerah, Penyiapan pelaksanaan monitoring dan evaluasi pinjaman dan hibah, obligasi daerah, dan dana bergulir, dan penyertaan modal daerah   ', '', '', 1, 1, 1, '');
INSERT INTO `klasifikasi_arsips` VALUES (2889, NULL, '2023-04-18 00:00:00', '2023-04-18 00:00:00', '900.1.14 Fasilitasi Dana Perimbangan   ', '', '', 1, 1, 1, '');
INSERT INTO `klasifikasi_arsips` VALUES (2890, NULL, '2023-04-18 00:00:00', '2023-04-18 00:00:00', '900.1.14.1 Fasilitasi Dana Alokasi Umum Antara lain: Koordinasi penyiapan data dasar penghitungan, dan rekonsiliasi dana alokasi umum, Sosialisasi dan supervisi dana alokasi umum, Penyiapan  pelaksanaan monitoring dan evaluasi dana alokasi umum ', '', '', 1, 1, 1, '');
INSERT INTO `klasifikasi_arsips` VALUES (2891, NULL, '2023-04-18 00:00:00', '2023-04-18 00:00:00', '900.1.14.2 Fasilitasi Dana Alokasi Khusus Antara lain: Koordinasi penyiapan data dasar, Sosialisasi dan supervisi dana alokasi khusus, penyiapan pelaksanaan monitoring, evaluasi dana alokasi khusus, Penyiapan pelaksanaan monitoring, evaluasi dana alokasi khusus ', '', '', 1, 1, 1, '');
INSERT INTO `klasifikasi_arsips` VALUES (2892, NULL, '2023-04-18 00:00:00', '2023-04-18 00:00:00', '900.1.14.3 Dana Bagi Hasil Pajak dan Sumber Daya Alam Antara lain: Koordinasi penyiapan data dasar perhitungan, dan rekonsiliasi dana bagi hasil pajak dan sumber daya alam, Sosialisasi dan supervisi dana bagi hasil pajak dan sumber daya alam, Penyiapan pelaksanaan monitoring dan evaluasi dana bagi hasil pajak dan sumber daya alam   ', '', '', 1, 1, 1, '');
INSERT INTO `klasifikasi_arsips` VALUES (2893, NULL, '2023-04-18 00:00:00', '2023-04-18 00:00:00', '900.1.14.4 Dana Otonomi Khusus dan Dana Transfer Lainnya Antara lain: Sosialisasi dan supervisi dana otonomi khusus, Sosialisasi dan supervisi dan transfer lainnya, Pelaksanaan monitoring dan evaluasi dan otonomi khusus dan dana transfer lainnya  ', '', '', 1, 1, 1, '');
INSERT INTO `klasifikasi_arsips` VALUES (2894, NULL, '2023-04-18 00:00:00', '2023-04-18 00:00:00', '900.1.14.5 Dukungan Teknis Fasilitasi Dana Perimbangan Antara lain: Penyiapan sinkronisasi kebijakan dan perimbangan, Penyiapan dukungan teknis dana perimbangan, Penyiapan data dan informasi untuk penyusunan laporan dana perimbangan   ', '', '', 1, 1, 1, '');
INSERT INTO `klasifikasi_arsips` VALUES (2895, NULL, '2023-04-18 00:00:00', '2023-04-18 00:00:00', '900.1.15 Pelaksanaan Dan Pertanggungjawaban Keuangan Daerah   ', '', '', 1, 1, 1, '');
INSERT INTO `klasifikasi_arsips` VALUES (2896, NULL, '2023-04-18 00:00:00', '2023-04-18 00:00:00', '900.1.15.1 Akuntansi Dan Pertanggungjawaban Keuangan Daerah Antara lain: Fasilitasi serta bimbingan teknis di bidang  akuntansi dan pertangungjawaban keuangan daerah, Penyiapan evaluasi rancangan peraturan daerah pertanggungjawaban keuangan daerah  ', '', '', 1, 1, 1, '');
INSERT INTO `klasifikasi_arsips` VALUES (2897, NULL, '2023-04-18 00:00:00', '2023-04-18 00:00:00', '900.1.15.2 Pembinaan Kinerja dan Kapasitas Pengelolaan Keuangan Daerah Antara lain: Fasilitasi serta bimbingan teknis di bidang pembinaan kinerja dan kapasitas pengelolaan keuangan daerah, Penyiapan evaluasi rancangan peraturan daerah pertangungjawaban keuangan daerah  ', '', '', 1, 1, 1, '');
INSERT INTO `klasifikasi_arsips` VALUES (2898, NULL, '2023-04-18 00:00:00', '2023-04-18 00:00:00', '900.1.15.3 Pembinaan dan Evaluasi Pengelolaan Keuangan Daerah Antara lain: Fasilitasi serta bimbingan teknis di bidang pembinaan dan evaluasi pengelolaan  keuangan daerah, Penyiapan evaluasi rancangan peraturan daerah pertangungjawaban keuangan daerah ', '', '', 1, 1, 1, '');
INSERT INTO `klasifikasi_arsips` VALUES (2899, NULL, '2023-04-18 00:00:00', '2023-04-18 00:00:00', '900.1.15.4 Kajian Kebijakan dan Bantuan Keterangan Ahli Antara lain: Penyiapan bahan bantuan keterangan ahli di bidang keuangan daerah, Penyiapan evaluasi rancangan peraturan daerah pertanggungjawaban keuangan daerah  ', '', '', 1, 1, 1, '');
INSERT INTO `klasifikasi_arsips` VALUES (2900, NULL, '2023-04-18 00:00:00', '2023-04-18 00:00:00', '900.1.15.5 Data Informasi dan Pengelolaan Keuangan Daerah Antara lain: Penyiapan sinkronisasi kebijakan pelaksanaan pertangungjawaban pelaksanaan keuangan daerah, Penyiapan data dan informasi untuk penyusunan laporan pertangungjawaban pelaksanaan keuangan daerah, Pengelolaan sistem informasi pengelolaan keuangan daerah ', '', '', 1, 1, 1, '');
